krpano.action:
if(lock_state != true, 
  set(lock_state, true);

  if(lock_saved != 1,
    set(lock_saved, 1);
    copy(_old_usercontrol, control.usercontrol);
    copy(_old_mouse,       control.mouse);
    copy(_old_touch,       control.touch);
    copy(_old_wheel,       control.wheel);
    copy(_old_zoom,        control.zoom);
    copy(_old_dragging,    control.dragging);
    copy(_old_vr_enabled,  vr.enabled);

  );

tween(view.hlookat, get(scene[get(xml.scene)].hlookat), 5.0);
  tween(view.vlookat, get(scene[get(xml.scene)].vlookat), 5.0);

set(control.usercontrol, off);
  set(control.mouse, off);
  set(control.touch, off);
  set(control.wheel, off);

set(control.invert_drag, false);
  set(control.fovspeed, 0);
  set(control.zoomspeed, 0);

set(vr.enabled, false);
);

if(lock_state == true, 
  set(lock_state, false);

  if(lock_saved == 1,
    set(control.usercontrol, get(_old_usercontrol));
    set(control.mouse,       get(_old_mouse));
    set(control.touch,       get(_old_touch));
    set(control.wheel,       get(_old_wheel));

set(vr.enabled,          get(_old_vr_enabled));

    set(lock_saved, 0);
  ,

set(control.usercontrol, all);
    set(control.mouse, drag);
    set(control.touch, drag);
    set(control.wheel, on);
  );
);
